#!/usr/bin/env python3
"""Own MIT hash logical case API probes; external Harbour oracle only."""
from pathlib import Path
import subprocess,json,hashlib,argparse,os
p=argparse.ArgumentParser();p.add_argument('--compiler',required=True);p.add_argument('--baseline',required=True);p.add_argument('--hbmk2',required=True);p.add_argument('--output',required=True);a=p.parse_args();out=Path(a.output).resolve();out.mkdir(exist_ok=False);env=dict(os.environ,PATH='/tmp/toolchain/bin:'+os.environ['PATH']);rows=[]
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(cmd,w,label):
 r=subprocess.run(list(map(str,cmd)),capture_output=True,env=env,timeout=30)
 for ext,v in [('stdout',r.stdout),('stderr',r.stderr),('rc',str(r.returncode).encode())]:(w/(label+'.'+ext)).write_bytes(v)
 return r
programs={'getter': 'function Main()\nlocal h:={=>}\n? hb_HCaseMatch(h)\nreturn nil\n', 'setter-return': 'function Main()\nlocal h:={=>}\n? hb_HCaseMatch(h,.F.)\n? hb_HCaseMatch(h,.T.)\n? hb_HCaseMatch(h,.T.)\nreturn nil\n', 'case-store': 'function Main()\nlocal h:={=>}\nhb_HCaseMatch(h,.F.)\nh["Host"]:=1\nh["HOST"]:=2\n? Len(h),h["host"],hb_HHasKey(h,"hOsT")\nreturn nil\n', 'keys-spelling': 'function Main()\nlocal h:={=>},keys:=hb_HKeys(h)\nhb_HCaseMatch(h,.F.)\nh["Host"]:=1\nh["HOST"]:=2\nkeys:=hb_HKeys(h)\n? keys[1],hb_HKeyAt(h,1),Len(h)\nreturn nil\n', 'clone-case': 'function Main()\nlocal h:={=>},k:={=>}\nhb_HCaseMatch(h,.F.)\nh["Host"]:=1\nk:=hb_HClone(h)\n? k["HOST"],hb_HCaseMatch(k)\nreturn nil\n', 'setflag-bool': 'function Main()\nlocal h:={=>}\nhb_HSetCaseMatch(h,.F.)\nh["Host"]:=1\n? h["HOST"]\nreturn nil\n', 'clone-flag-only': 'function Main()\nlocal h:={=>},k:={=>}\nhb_HCaseMatch(h,.F.)\nk:=hb_HClone(h)\nk["Host"]:=1\n? k["HOST"]\nreturn nil\n', 'numeric-kind-case': 'function Main()\nlocal h:={=>}\nhb_HCaseMatch(h,.F.)\nh[65]:=1\nh[97]:=2\n? Len(h),h[65],h[97]\nreturn nil\n', 'collapse-existing': 'function Main()\nlocal h:={"a"=>1,"A"=>2},keys:=hb_HKeys(h)\n? Len(h),hb_HCaseMatch(h,.F.),Len(h),h["a"],h["A"]\nkeys:=hb_HKeys(h)\n? Len(keys),keys[1]\nreturn nil\n', 'nested-flag': 'function Main()\nlocal h:={=>}\n? hb_HCaseMatch(h,hb_HCaseMatch(h,.F.)),hb_HCaseMatch(h)\nreturn nil\n', 'getter-before-after': 'function Main()\nlocal h:={=>}\n? hb_HCaseMatch(h),hb_HCaseMatch(h,.F.),hb_HCaseMatch(h),hb_HCaseMatch(h,.T.),hb_HCaseMatch(h)\nreturn nil\n', 'clear-mode': 'function Main()\nlocal h:={=>}\nhb_HCaseMatch(h,.F.)\nh["a"]:=1\nhb_HClear(h)\n? hb_HCaseMatch(h)\nh["a"]:=2\n? hb_HHasKey(h,"A")\nreturn nil\n', 'flag-expression': 'function Flag()\n? "flag"\nreturn .F.\nfunction Main()\nlocal h:={=>}\n? hb_HCaseMatch(h,Flag()),hb_HCaseMatch(h)\nreturn nil\n', 'logical-slot': 'function Main()\nlocal h:={=>},f:=.F.,old:=.F.\nold:=hb_HCaseMatch(h,f)\n? old,hb_HCaseMatch(h),ValType(old)\nreturn nil\n', 'logical-flow': 'function Main()\nlocal h:={=>}\nif hb_HCaseMatch(h)\n? "true"\nendif\nif !hb_HCaseMatch(h,.F.)\n? "wrong"\nendif\nif !hb_HCaseMatch(h)\n? "false"\nendif\nreturn nil\n', 'clear-owned': 'function Main()\nlocal h:={=>}\nhb_HCaseMatch(h,.F.)\nh["Host"]:="value"\nhb_HClear(h)\nh["Host"]:="new"\n? h["HOST"],hb_HCaseMatch(h)\nreturn nil\n', 'numeric-clear': 'function Main()\nlocal h:={=>}\nhb_HCaseMatch(h,.F.)\nh[65]:=1\nh[97]:=2\nhb_HClear(h)\nh[65]:=3\nh[97]:=4\n? Len(h),h[65],h[97],hb_HCaseMatch(h)\nreturn nil\n'}
for name,text in programs.items():
 w=out/name;w.mkdir();src=w/'p.prg';src.write_text(text);row=dict(name=name,source_sha256=h(src),results={})
 for label,cmd in [('base',[a.baseline,src,w/'base','--target=linux']),('int',[a.compiler,src,w/'int','--target=linux']),('ext',[a.compiler,src,w/'ext','--target=linux','--external-as']),('oracle',[a.hbmk2,src,'-quiet','-w0','-gtstd','-o'+str(w/'oracle')])]:
  b=run(cmd,w,label+'-build');rr=dict(build_rc=b.returncode)
  if not b.returncode:
   q=run([w/label],w,label+'-run');rr.update(run_rc=q.returncode,binary_sha256=h(w/label));(w/label).unlink()
  row['results'][label]=rr
 for label in ['oracle','int','ext']:assert row['results'][label]['build_rc']==0,(name,label)
 for label in ['int','ext']:assert all((w/(label+'-run.'+ext)).read_bytes()==(w/('oracle-run.'+ext)).read_bytes() for ext in ['rc','stdout','stderr']),(name,label)
 rows.append(row);print(name,'EXACT int/ext',flush=True)
(out/'results.json').write_text(json.dumps(dict(compiler_sha256=h(Path(a.compiler)),baseline_sha256=h(Path(a.baseline)),runner_sha256=h(Path(__file__)),scope='Own hash logical case API and clear-preserve sources, int/ext exact rc/stdout/stderr against external Harbour. Baseline build rejections separate.',rows=rows),indent=2))
